# -*- coding: utf-8 -*-
"""ped32_cards_data.py — PED-32: Tiếp cận trẻ Sốt & Sốt chưa rõ nguyên nhân (FUO).
Basic-first Master deck (B0-B16) + cloze nhắc phụ giữ lịch sử ôn."""

ALGO = "⚡ THUẬT TOÁN QUYẾT ĐỊNH"


def _s(color, t):
    return '<span style="color:' + color + '"><b>' + t + '</b></span>'


def R(t):
    return _s('#ff6b6b', t)


def Y(t):
    return _s('#ffd43b', t)


def G(t):
    return _s('#51cf66', t)


def L(t):
    return _s('#74c0fc', t)


def basic(cid, sec, cat, tier, front, answers, expl, src, algo=False):
    back = '<b>🎯 Trả lời cốt lõi:</b><br>' + '<br>'.join(
        str(i + 1) + ') ' + a for i, a in enumerate(answers)
    ) + '<br><br><b>💡 Giải thích của AI:</b><br>' + expl
    c = {
        "id": cid, "type": "basic", "track": "ebm", "section": sec,
        "category": cat, "tier": tier, "front": front, "back": back,
        "extra": "📖 Nguồn: " + src, "tags": ["PED-32", sec, "ALGO" if algo else "EBM"],
    }
    if algo:
        c["badge"] = ALGO
        c["badge_class"] = "badge-algo"
    return c


def cloze(cid, sec, text, src, legacy):
    return {"id": cid, "type": "cloze", "section": sec, "text": text,
            "extra": "📖 Nguồn: " + src, "legacy_note_id": legacy}


